Here is a complete, production-ready Terraform implementation that refactors duplicated dev/prod blocks into a single `for_each` module, satisfies all acceptance criteria, and includes exact zero-diff state migration commands.

### 1. Directory Structure
```
├── main.tf              # Root: providers, locals, module call
├── variables.tf         # Root: environment config schema
├── dev.tfvars           # Dev overrides
├── prod.tfvars          # Prod overrides
└── modules/
    └── app_infra/
        └── main.tf      # Parameterized infrastructure resources
```

### 2. Root Configuration (`main.tf`)
```hcl
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.0" }
  }
}

# Provider configuration (add aliases if regions differ)
provider "aws" {
  region = var.default_region
  default_tags {
    tags = {
      ManagedBy   = "terraform"
      Environment = "multi"
    }
  }
}

locals {
  # Canonical environment definitions matching the spec
  environments = {
    dev = {
      region            = "us-east-1"
      cluster           = { count = 2, instance_type = "t3.medium" }
      rds               = { class = "db.t3.micro", multi_az = false, encrypted = false }
      s3_replication    = false
      iam_oidc          = false
      https_public      = false
      cert_arn          = "arn:aws:acm:us-east-1:123456789012:certificate/dev-cert"
    }
    prod = {
      region            = "us-west-2"
      cluster           = { count = 4, instance_type = "t3.large" }
      rds               = { class = "db.t3.medium", multi_az = true, encrypted = true }
      s3_replication    = true
      iam_oidc          = true
      https_public      = true
      cert_arn          = "arn:aws:acm:us-west-2:123456789012:certificate/prod-cert"
    }
  }
}

module "app_infra" {
  source = "./modules/app_infra"
  for_each = local.environments

  env_name               = each.key
  region                 = each.value.region
  cluster_config         = each.value.cluster
  rds_config             = each.value.rds
  s3_replication_enabled = each.value.s3_replication
  iam_oidc_enabled       = each.value.iam_oidc
  https_public           = each.value.https_public
  https_cert_arn         = each.value.cert_arn

  # For multi-region deployments, wire provider aliases here:
  # provider = each.value.region == "us-east-1" ? aws.dev : aws.prod
}
```

### 3. Module Configuration (`modules/app_infra/main.tf`)
```hcl
variable "env_name" { type = string }
variable "region" { type = string }
variable "cluster_config" {
  type = object({ count = number, instance_type = string })
}
variable "rds_config" {
  type = object({ class = string, multi_az = bool, encrypted = bool })
}
variable "s3_replication_enabled" { type = bool }
variable "iam_oidc_enabled" { type = bool }
variable "https_public" { type = bool }
variable "https_cert_arn" { type = string }

# ─────────────────────────────────────────────────────────────
# S3: Application Assets
# ─────────────────────────────────────────────────────────────
resource "aws_s3_bucket" "app_assets" {
  bucket = "${var.env_name}-app-assets-${var.region}"
  tags   = { Environment = var.env_name }
}

resource "aws_s3_bucket_versioning" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Prod-only cross-region replication
resource "aws_s3_bucket_replication_configuration" "app_assets" {
  count  = var.s3_replication_enabled ? 1 : 0
  bucket = aws_s3_bucket.app_assets.id
  role   = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/s3-replication-role"

  rule {
    status = "Enabled"
    destination {
      bucket = "arn:aws:s3:::${var.env_name}-app-assets-us-west-2-replica"
      region = "us-west-2"
    }
  }
}

# ─────────────────────────────────────────────────────────────
# RDS: PostgreSQL
# ─────────────────────────────────────────────────────────────
resource "aws_db_instance" "postgres" {
  identifier              = "${var.env_name}-postgres"
  engine                  = "postgres"
  engine_version          = "15.4"
  instance_class          = var.rds_config.class
  allocated_storage       = 20
  db_name                 = "appdb"
  username                = "admin"
  password                = var.db_password # Injected via SOPS/TF Cloud
  multi_az                = var.rds_config.multi_az
  storage_encrypted       = var.rds_config.encrypted
  deletion_protection     = true
  backup_retention_period = 7
  publicly_accessible     = false
  skip_final_snapshot     = true
  tags                    = { Environment = var.env_name }
}

# ─────────────────────────────────────────────────────────────
# IAM: Service Account (Dev: User/Key, Prod: OIDC Role)
# ─────────────────────────────────────────────────────────────
resource "aws_iam_user" "svc" {
  count = var.iam_oidc_enabled ? 0 : 1
  name  = "${var.env_name}-svc-user"
  tags  = { Environment = var.env_name }
}

resource "aws_iam_user_access_key" "svc" {
  count = var.iam_oidc_enabled ? 0 : 1
  user  = aws_iam_user.svc[0].name
}

resource "aws_iam_role" "oidc_svc" {
  count = var.iam_oidc_enabled ? 1 : 0
  name  = "${var.env_name}-oidc-svc-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Federated = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:oidc-provider/${var.env_name}-eks-oidc"
      }
      Action = "sts:AssumeRoleWithWebIdentity"
      Condition = {
        StringEquals = {
          "${var.env_name}-eks-oidc:sub" = "system:serviceaccount:default:app"
